---
/**
 * @title Button
 * @level liftoff
 * @description Themed, copy-paste action button built atop OriginButton. Adds semantic token variants, sizes, hover/press/focus states, and WCAG 2.5.8 / 2.5.5 minimum target sizing. For URL navigation, use LinkButton instead.
 * @category Actions
 * @hydration optional
 * @accessibility
 * - Delegates HTML semantics, safe `type="button"` default, `aria-disabled` focus preservation, and declarative triggers directly to `@lsui/origin` (`OriginButton`).
 * - Enforces >= 24x24px minimum target on desktop and >= 44x44px on coarse touch pointers (`--target-min-size`).
 * - Icon-only buttons (`iconOnly`) require an explicit `aria-label` at compile time.
 * @keyboard
 * - `Enter` / `Space`: Activates the button (and dispatches `command` / toggles `popovertarget` when configured).
 * @slots
 * - `default`: Visible button label text.
 * - `icon-start`: Optional leading decorative icon (`aria-hidden="true"` on SVGs).
 * - `icon-end`: Optional trailing decorative icon (`aria-hidden="true"` on SVGs).
 */

import OriginButton from "@lsui/origin/Button.astro";
import type { InvokerCommand } from "@lsui/origin";
import type { HTMLAttributes } from "astro/types";
import type { ButtonVariant, ControlSize } from "../../contract.ts";
import "./button.css";

type NativeButtonAttributes = Omit<
  HTMLAttributes<"button">,
  "type" | "command" | "commandfor" | "popovertarget" | "popovertargetaction"
>;

interface BaseButtonProps extends NativeButtonAttributes {
  /** Visual style token variant. */
  variant?: ButtonVariant | undefined;
  /** Control height and padding scale. */
  size?: ControlSize | undefined;
  /** Safe element tag override (`"button"` default; `"a"` is forbidden—use `LinkButton` instead). */
  as?: "button" | "span" | "div" | undefined;
  /** Native button behavior (`"button"` by default so forms never submit accidentally). */
  type?: "button" | "submit" | "reset" | undefined;
  /** Disables the button and removes it from tab order. Use `aria-disabled="true"` when focus must remain reachable. */
  disabled?: boolean | undefined;
  /** Conditionally renders the component when `true` (omits markup when `false`). */
  render?: boolean | undefined;
  /** Target element ID for the HTML Invoker Commands API (`https://webstatus.dev/features/invoker-commands`). */
  commandfor?: string | undefined;
  /** Built-in or `--custom` command dispatched to `commandfor`. */
  command?: InvokerCommand | undefined;
  /** Target element ID for the HTML Popover API (`https://webstatus.dev/features/popover`). */
  popovertarget?: string | undefined;
  /** Popover action performed when clicked. */
  popovertargetaction?: "toggle" | "show" | "hide" | undefined;
  /** Never pass `href` to `<Button>`; use `<LinkButton href="...">` to preserve native link semantics. */
  href?: never;
}

export type Props = BaseButtonProps &
  (
    | {
        iconOnly?: false | undefined;
        "aria-label"?: string | undefined;
      }
    | {
        iconOnly: true;
        "aria-label": string;
      }
  );

const {
  variant = "primary",
  size = "md",
  iconOnly = false,
  "aria-label": ariaLabel,
  ...rest
} = Astro.props;

const hasStartSlot = Astro.slots.has("icon-start");
const hasEndSlot = Astro.slots.has("icon-end");
---

{
  iconOnly ? (
    <OriginButton
      data-lsui-button=""
      data-variant={variant}
      data-size={size}
      iconOnly={true}
      aria-label={ariaLabel as string}
      {...rest}
    >
      {hasStartSlot && <slot name="icon-start" slot="icon-start" />}
      <slot />
      {hasEndSlot && <slot name="icon-end" slot="icon-end" />}
    </OriginButton>
  ) : (
    <OriginButton
      data-lsui-button=""
      data-variant={variant}
      data-size={size}
      aria-label={ariaLabel}
      {...rest}
    >
      {hasStartSlot && <slot name="icon-start" slot="icon-start" />}
      <slot />
      {hasEndSlot && <slot name="icon-end" slot="icon-end" />}
    </OriginButton>
  )
}

/* LightSpeedUI Level 2 (@lsui/liftoff) — Shared Visual Styles for <Button> and <LinkButton>
 *
 * Layers semantic token styling (`@layer lsui.components`) on top of Level 1 (@lsui/origin)
 * unstyled primitives. Consumes semantic CSS custom properties exclusively.
 */

@layer lsui {
  @layer components {
    [data-lsui-button] {
      --btn-height: var(--control-height-md);
      --btn-pad-inline: var(--control-pad-inline-md);
      --btn-font-size: var(--text-sm);
      --btn-gap: var(--space-2);

      position: relative;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: var(--btn-gap);
      box-sizing: border-box;

      /* Flexible block sizing (never fixed height) + WCAG 2.5.8 / 2.5.5 target floor */
      min-block-size: max(var(--btn-height), var(--target-min-size, 1.5rem));
      min-inline-size: var(--target-min-size, 1.5rem);
      padding-block: var(--space-1);
      padding-inline: var(--btn-pad-inline);

      border: var(--border-width) solid transparent;
      border-radius: var(--radius-md);
      font-family: var(--font-body);
      font-size: var(--btn-font-size);
      font-weight: var(--weight-medium);
      line-height: var(--leading-snug);
      text-align: center;
      text-decoration: none;
      user-select: none;
      vertical-align: middle;

      transition:
        background-color var(--duration-fast) var(--ease-standard),
        border-color var(--duration-fast) var(--ease-standard),
        color var(--duration-fast) var(--ease-standard),
        box-shadow var(--duration-fast) var(--ease-standard),
        scale var(--duration-fast) var(--ease-standard);
    }

    button[data-lsui-button],
    [data-lsui-simulated-button][data-lsui-button] {
      cursor: var(--cursor-interactive, default);
    }

    a[data-lsui-button][href] {
      cursor: pointer;
    }

    [data-lsui-button] :where(svg) {
      inline-size: 1.125em;
      block-size: 1.125em;
      flex-shrink: 0;
      pointer-events: none;
    }

    /* ---- Sizes ---- */
    [data-lsui-button][data-size="sm"] {
      --btn-height: var(--control-height-sm);
      --btn-pad-inline: var(--control-pad-inline-sm);
      --btn-font-size: var(--text-xs);
      --btn-gap: var(--space-1);
      border-radius: var(--radius-sm);
    }

    [data-lsui-button][data-size="md"] {
      --btn-height: var(--control-height-md);
      --btn-pad-inline: var(--control-pad-inline-md);
      --btn-font-size: var(--text-sm);
    }

    [data-lsui-button][data-size="lg"] {
      --btn-height: var(--control-height-lg);
      --btn-pad-inline: var(--control-pad-inline-lg);
      --btn-font-size: var(--text-base);
      --btn-gap: var(--space-3);
    }

    [data-lsui-button][data-icon-only] {
      padding-inline: 0;
      min-inline-size: max(var(--btn-height), var(--target-min-size, 1.5rem));
    }

    /* ---- Variants ---- */
    [data-lsui-button][data-variant="primary"] {
      background-color: var(--color-primary);
      color: var(--color-on-primary);
      border-color: transparent;

      &:hover:not(:disabled):not([aria-disabled="true"]) {
        background-color: var(--color-primary-hover);
        box-shadow: var(--shadow-sm);
      }
    }

    [data-lsui-button][data-variant="secondary"] {
      background-color: var(--color-secondary);
      color: var(--color-on-secondary);
      border-color: var(--color-border);

      &:hover:not(:disabled):not([aria-disabled="true"]) {
        background-color: var(--color-secondary-hover);
        border-color: var(--color-border-strong);
      }
    }

    [data-lsui-button][data-variant="outline"] {
      background-color: transparent;
      color: var(--color-text);
      border-color: var(--color-border-strong);

      &:hover:not(:disabled):not([aria-disabled="true"]) {
        background-color: color-mix(in oklab, var(--color-text) 8%, transparent);
        border-color: var(--color-text);
        box-shadow: var(--shadow-sm);
      }
    }

    [data-lsui-button][data-variant="ghost"] {
      background-color: transparent;
      color: var(--color-text);
      border-color: transparent;

      &:hover:not(:disabled):not([aria-disabled="true"]) {
        background-color: color-mix(in oklab, var(--color-text) 9%, transparent);
      }
    }

    [data-lsui-button][data-variant="danger"] {
      background-color: var(--color-danger);
      color: var(--color-on-danger);
      border-color: transparent;

      &:hover:not(:disabled):not([aria-disabled="true"]) {
        background-color: var(--color-danger-hover);
        box-shadow: var(--shadow-sm);
      }
    }

    @media (prefers-reduced-motion: no-preference) {
      [data-lsui-button]:active:not(:disabled):not([aria-disabled="true"]) {
        scale: 0.98;
      }
    }

    :where([data-motion="reduced"], [data-motion="none"]) [data-lsui-button]:active {
      scale: none;
    }

    [data-lsui-button]:focus-visible {
      outline: var(--ring-width) solid var(--color-ring);
      outline-offset: var(--ring-offset);
    }

    [data-lsui-button]:is(:disabled, [aria-disabled="true"]) {
      /* Never dim the whole element: opacity also fades the label and focus ring.
       * Full-strength semantic text + a subtle surface-derived fill keeps focusable
       * `aria-disabled` labels legible; the dashed border is a non-color state cue. */
      background-color: color-mix(in oklab, var(--color-surface) 88%, var(--color-text));
      color: var(--color-text);
      border-color: var(--color-border);
      border-style: dashed;
      box-shadow: none;
      cursor: not-allowed;
    }
  }
}
